mapper.update:
update t_order_item
set refunded_qty = refunded_qty + #{quantity}, update_time = CURRENT_TIMESTAMP
where id = #{id}

update t_order_item
set refund_frozen_qty = refund_frozen_qty + #{qty},
    refund_frozen_amount = refund_frozen_amount + #{amount},
    update_time = CURRENT_TIMESTAMP
where id = #{id}
  and quantity - refunded_qty - refund_frozen_qty >= #{qty}
  and pay_amount - refunded_amount - refund_frozen_amount >= #{amount}

update t_order_item
set refund_frozen_qty = refund_frozen_qty - #{qty},
    refund_frozen_amount = refund_frozen_amount - #{amount},
    update_time = CURRENT_TIMESTAMP
where id = #{id}
  and refund_frozen_qty >= #{qty}
  and refund_frozen_amount >= #{amount}

update t_order_item
set refund_frozen_qty = refund_frozen_qty - #{qty},
    refund_frozen_amount = refund_frozen_amount - #{amount},
    refunded_qty = refunded_qty + #{qty},
    refunded_amount = refunded_amount + #{amount},
    update_time = CURRENT_TIMESTAMP
where id = #{id}
  and refund_frozen_qty >= #{qty}
  and refund_frozen_amount >= #{amount}
